KONTROL = '9999999999'
DROP = r'C:\seostat\drop\drop-storage'
c = sqlite3.connect(r'C:\sender\enrich.db').cursor()
kont, povod = [], []
for i in INN + [KONTROL]:
    for p, r, ph, em, su, url in c.execute(
            "select post, role, phone, email, source, source_url from people where inn=?", (i,)):
        kont.append({'inn': i, 'chelovek_dolzhnost': p or '', 'rol_kanon': r or '',
                     'telefon': ph or '', 'pochta': em or '', 'istochnik': su or '',
                     'ssylka': url or '', 'otkuda': 'people'})
    for ph, r, su, url in c.execute(
            "select phone, role, source, source_url from phone_contacts where inn=? limit 40", (i,)):
        kont.append({'inn': i, 'chelovek_dolzhnost': '', 'rol_kanon': r or '',
                     'telefon': ph or '', 'pochta': '', 'istochnik': su or '',
                     'ssylka': url or '', 'otkuda': 'phone_contacts'})
    for et, wt, sm, su, url, ts in c.execute(
            "select event_type, what, sum, source, source_url, ts from signals where inn=? limit 12", (i,)):
        povod.append({'inn': i, 'tip_sobytiya': et or '', 'chto': (wt or '')[:400],
                      'summa': sm or '', 'istochnik': su or '', 'ssylka': url or '', 'kogda': ts or ''})
kk = len([x for x in kont if x['inn'] == KONTROL]); kp = len([x for x in povod if x['inn'] == KONTROL])
kont = [x for x in kont if x['inn'] != KONTROL]; povod = [x for x in povod if x['inn'] != KONTROL]
def polozhit(imya, stroki, polya):
    with io.open(os.path.join(DROP, imya), 'w', encoding='utf-8-sig', newline='') as f:
        w = csv.DictWriter(f, fieldnames=polya, delimiter=';'); w.writeheader()
        for s in stroki: w.writerow(s)
polozhit('3s_PROIZV-KONTAKTY.csv', kont, ['inn','chelovek_dolzhnost','rol_kanon','telefon','pochta','istochnik','ssylka','otkuda'])
polozhit('3s_PROIZV-POVODY.csv', povod, ['inn','tip_sobytiya','chto','summa','istochnik','ssylka','kogda'])
